INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The White Door', 'Robert Hill wakes up in a Mental Health facility and suffers from severe memory loss. Follow the strict daily routine of the facility and help him to recollect his memories by exploring his dreams. The White Door is a point-and-click adventure by Rusty Lake that uses a split-screen for interaction with the environment and protagonist. The release is planned for iOS, Android, Steam and itch.io at the end of summer 2019.' FROM games WHERE igdb_id = 120552 ON CONFLICT (game_id, language_code) DO NOTHING;
