INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Anime: World War II', 'In this third-person WWII-themed shooter H.E.N.T.A.I. battalion is on a huge mission of clearing out the fallen city from enemies. There are a couple of winning strategies you might want to choose depending on the type of weapon in your hands. Choose wisely: there is no map of what''s left of the city, and there is little to no information about how much enemies left.' FROM games WHERE igdb_id = 148702 ON CONFLICT (game_id, language_code) DO NOTHING;
