INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Mead Crafter', 'Mead Crafter is a casual match-three game set in medieval times that lets you build a thriving business as a mead maker. Click colorful icons to fill your customers’ orders for different types of mead flavored with various fruits and spices. Earn coins every round to cover monthly rent costs or buy various skill improvements that help you grow your business. Can you keep up with new orders and master all the skills needed to earn official recognition from the King?' FROM games WHERE igdb_id = 139122 ON CONFLICT (game_id, language_code) DO NOTHING;
