INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Tetris Effect: Connected', 'Tetris Effect: Connected adds an all-new robust multiplayer expansion to the huge variety of addictive and innovative single-player modes that Tetris Effect is known for. Connect and play with or against each other in all-new modes like "Zone Battle," which shakes up traditional 1-on-1 Tetris gameplay via the time-stopping Zone mechanic, or try the innovative co-op of "Connected" mode, where up to three players can literally connect their Tetris playfields together and play as one, as they work together to take down a series of increasingly-challenging CPU-controlled bosses.' FROM games WHERE igdb_id = 135999 ON CONFLICT (game_id, language_code) DO NOTHING;
