INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Sok-Worlds', 'Sok-Worlds is a game/toy where you make and explore 3d collage worlds. Search a big library of images and add them to your world. Assemble them, cut them out, add text, add some music and create all kinds of cool, weird places to explore! Upload your creations to the sok-worlds library and share them with the world. Find creations by other makers and check out what they''ve made!' FROM games WHERE igdb_id = 132036 ON CONFLICT (game_id, language_code) DO NOTHING;
