INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('vessels', 141520, '2020-12-08', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2mdz.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar10i4.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Vessels', 'Vessels is an atmospheric, character-driven narrative adventure game. Players assume the role of crewmember quarantined in the airlock of their ship with no memory of how they got there, and with crewmates who refuse to let you out. Players can posses other crew members to explore the ship and find a way to free yourself, where different choices can lead to multiple endings.' FROM games WHERE igdb_id = 141520 ON CONFLICT (game_id, language_code) DO NOTHING;
