INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('2weistein-the-curse-of-the-red-dragon', 147439, '2020-09-13', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co4e6o.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar959.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', '2weistein: The Curse of the Red Dragon', 'The Story All was peace and quiet in Asban and the whole land of Trillion – until that day on which the gates remained closed, as if by ghostly hand, and other strange things happened. The mean magician Godron has stolen the book „Mathematica“ from the creator of Trillion, and has cast an evil spell over the city: a ban on mathematics. Godron wants to gain power over the whole land and transform the world according to his will. But there are the brave heroes Bernard and Celestine with their friend 2weistein who want to put a stop to Godron to keep Trillion peaceful and beautiful, and no on is ever to be afraid again! About the 2weistein games The unique and fantastic idea behind the series of 2weistein games is to train maths in a real 3D action adventure. Embedded in the tantalizing story the player has to solve maths quests or puzzles to get ahead in the game. It was developed by game specialists in cooperation with teachers and psychologists and won several prices and awards in Germany and Austria.' FROM games WHERE igdb_id = 147439 ON CONFLICT (game_id, language_code) DO NOTHING;
