INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('yandere-no-sutoka', 285048, '2020-10-31', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/cobpvb.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar5ido.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Yandere no Sutoka', 'Saiko No Sutoka is a survival horror game set in Akademi High School where players must escape from a yandere character while navigating the school environment. Players search for an exit key to escape while avoiding either Ayano or Ayato, who actively hunts them throughout the building. The game features stealth mechanics including hiding in lockers, audio cues through heartbeat sounds that intensify as the pursuer approaches, and environmental hazards such as trip wires and thrown knives. If the yandere loses track of the player for an extended period, they will cut the power to darken the environment and continue their pursuit. The game combines elements of hide-and-seek gameplay with tension-building mechanics in a school setting.' FROM games WHERE igdb_id = 285048 ON CONFLICT (game_id, language_code) DO NOTHING;
