INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('exit-the-gungeon', 122311, '2020-03-16', 70, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co1xmt.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/arc3i.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Exit the Gungeon', 'Exit the Gungeon is a bullet hell dungeon climber immediately following the adventures of the misfit ‘Gungeoneers’ and their journey for personal absolution in Enter the Gungeon. The Gungeon has become a paradox and is collapsing! Armed with an ever-changing weapon, an insatiable need to loot, and the trusty dodge roll, each of our heroes must ascend and escape via their own unique route of increasingly perilous elevators. Battle against the last and most bitter of the Gundead at a frantic pace, slowing down just long enough to chat with some familiar faces… and a few new ones. Shifting rooms, enemies, bosses, bizarre weapons and items all combine to ensure that no two attempts to Exit the Gungeon are the same.' FROM games WHERE igdb_id = 122311 ON CONFLICT (game_id, language_code) DO NOTHING;
