INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Warhammer Underworlds: Online', 'Warhammer Underworlds: Online offers high-stakes, turn-based strategy that pits mighty warbands against one another in an eternal battle for Glory in the realms of the Age of Sigmar. The streamlined fighter count of Warhammer Underworlds: Online makes it both easy to grasp and quick to play, while its dice-and-cards mechanics offer boundless strategic depth. Choose a warband, build your power and objective decks, roll the dice and carve a path to victory.' FROM games WHERE igdb_id = 117743 ON CONFLICT (game_id, language_code) DO NOTHING;
