INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Tarzan VR', 'Tarzan VR is an episodic, single player virtual reality game with carefully balanced elements of exploration, combat, athletics, creature interaction and natural wonder and is experienced as multiple serialized comic-style issues to explore and conquer. Players can swing, swim, climb and fight their way across five open world environments, each offering its own unique set of geographical landscapes and challenges. Additionally, players will have access to unique Tarzan "jungle skills" such as Call of the Wild, Earth Vision and Fish Eye.' FROM games WHERE igdb_id = 121058 ON CONFLICT (game_id, language_code) DO NOTHING;
