INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Cannibal Cuisine', 'The god Hoochooboo is hungry… for you. But as all good cannibal cooks know, serving is better than being served. Chop up vegetables, fruits and tourists and serve your divine delicacies arcade style with up to 4 chefs in Cannibal Cuisine! Ready, steady, cook your way through many levels in a full campaign across the island. Overcome spikes in mysterious temples, bushwhack your way through tourist infested jungles and stay away from lava in the underground.' FROM games WHERE igdb_id = 125671 ON CONFLICT (game_id, language_code) DO NOTHING;
