INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Project:Pong', 'The Pong game is very simple, but what if there were two balls? What if there was fire in the middle? What if the whole field was frozen? What if there was a snake? A cannon? Ghosts? Bats? Wind? Water? Portals? This is the kind of ideas that inspired me in creating Project:Pong.' FROM games WHERE igdb_id = 149440 ON CONFLICT (game_id, language_code) DO NOTHING;
