INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('romance-of-the-three-kingdoms-xiv', 121231, '2020-01-16', 60, 'https://images.igdb.com/igdb/image/upload/t_cover_big/coaazb.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/arl4d.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Romance of the Three Kingdoms XIV', 'The latest iteration of the classic tactical series is once again set during the fall of the Han Dynasty in ancient China; where battles take place in a boundary-free scramble for land. The game’s map showcases the territory captured and the thrill of expansion using a simplified color system – paying homage to the original Romance of The Three Kingdoms XIV, released on PC back in 1985. Everything from war to diplomatic affairs will be geared toward managing and gathering land as players attempt to spread their strategies at will across the vast China map.' FROM games WHERE igdb_id = 121231 ON CONFLICT (game_id, language_code) DO NOTHING;
