INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Amnesia: Rebirth', 'Amnesia: Rebirth is a new descent into darkness from the creators of the iconic Amnesia series. Set in the desolate landscape of the Algerian desert, the game will focus on new character Tasi Trianon as she sets out on a harrowing journey through devastation and despair, personal terror and pain, while exploring the limits of human resilience.' FROM games WHERE igdb_id = 131785 ON CONFLICT (game_id, language_code) DO NOTHING;
