INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Gridiron', 'Gridiron is a fast-paced fusion of sci-fi and arcade-style football. Featuring easy to understand controls and a competitive multiplayer driven online experience. Gridiron features up to 7v7 both casual and competitive online matches, offline practice mode and much more!' FROM games WHERE igdb_id = 85968 ON CONFLICT (game_id, language_code) DO NOTHING;
