INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Desperados III: Collector''s Edition', 'The Wild West. A place where the law is made by those with a gun in their hands, and is enforced by the henchmen at their command. A place where death is no stranger and the undertakers are working overtime… especially when people start playing Desperados III. This real-time tactics game, developed by German game studio Mimimi Games (Shadow Tactics: Blades Of The Shogun), lets players command a band of Desperados led by fan-favourite gunslinger John Cooper.' FROM games WHERE igdb_id = 135983 ON CONFLICT (game_id, language_code) DO NOTHING;
