INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('spirit-of-the-north-enhanced-edition', 140437, '2020-11-26', 70, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2kwj.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar1044.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Spirit of the North: Enhanced Edition', 'Spirit of the North: Enhanced Edition is a single-player third-person adventure game inspired by the breathtaking and mysterious landscapes of Iceland. The story takes root from various pieces of Nordic folklore. Play as an ordinary fox whose story becomes entwined with The Guardian of the Northern Lights, a magical spirit fox. As you journey over the mountains and under red-stained skies, you’ll discover more about your companion and a land left in ruin. Uniquely designed to purposefully have no dialogue or narration. Players must breathe in their surroundings to solve various puzzles and speculate the meaning of a lost ancient civilization.' FROM games WHERE igdb_id = 140437 ON CONFLICT (game_id, language_code) DO NOTHING;
