INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Path of Titans', 'Path of Titans is a cross-platform indie game with MMO questing, where players choose from 30+ dinosaur species and survive, explore, and thrive through life cycle events and social gaming. Find and build a home cave within Panjura, the first of several 8km x 8km maps. Explore our open sandbox, or extend gameplay through an extensive system of MMO questing adventures for the menagerie of air land and sea dinosaurs, with rewards and incentives from egg to adult.' FROM games WHERE igdb_id = 122927 ON CONFLICT (game_id, language_code) DO NOTHING;
