INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Project Agent', 'Be the main actor in this suspenseful interactive spy thriller as you seek to escape your captors from their secret base. You are a secret agent, of the type that usually excels during every mission, through bravery and intelligence, not to mention your pretty good looks. But alas, your last mission ended in peril, for you were captured and must now attempt a daring escape!' FROM games WHERE igdb_id = 362631 ON CONFLICT (game_id, language_code) DO NOTHING;
