INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('elderborn', 74330, '2020-01-30', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co3diz.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar47o.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Elderborn', 'Elderborn is a Metal Action Fantasy Slasher with brutal FPP melee combat and souls-like/RPG character progression. In the times of legend, the barbarian tribes need a new dark messiah. The player becomes a merciless slayer who will uncover ancient secrets in the city of doom, and forge their own destiny. This ambitious indie game, five years in the making, combines old-school single-player feel, a classic heroic story, and modern level of skill-based challenge. All this and more creates an action-packed, lore-filled, engaging adventure that will last 8-10 hours in a single play-through.' FROM games WHERE igdb_id = 74330 ON CONFLICT (game_id, language_code) DO NOTHING;
