INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Akuarium', 'Akuarium: Underwater Adventure is a cutting-edge game that immerses players in the underwater world to fight dangerous predators and five bosses at the end of each level. Score coins and treasures while you explore. Fully detailed 3D Graphics make this game fully immersive. Beautifully painted underwater landscapes, spectacular special effects, glowing lights, sun flares and reflections are completely mesmerising.' FROM games WHERE igdb_id = 147471 ON CONFLICT (game_id, language_code) DO NOTHING;
