INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('miracle-sudoku', 153573, '2020-08-13', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co7hxs.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/arzir.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Miracle Sudoku', 'Miracle Sudoku features beautiful puzzles that at first glance look impossible to solve!! Indeed, some of our Miracle puzzles have as few as two givens digits (!) but you will find them all to be solvable with a bit of clever logic! At launch you will be able to play through 4 variants all of which make use of a non-consecutive restraint (ie neighboring cells cannot have two consecutive numbers in them). They are Non-Consecutive Sudoku, classic Miracle Sudoku (non-consecutive + knight + king restrictions), Non-Consecutive Thermo Sudoku and Non-Consecutive Sandwich Sudoku. Each of these variants has a unique feel which refreshes the logic you may be used to, especially in thermo and sandwich sudoku!' FROM games WHERE igdb_id = 153573 ON CONFLICT (game_id, language_code) DO NOTHING;
