INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Hide ''N Seek!', 'The good old classic hide & seek. Play either as a seeker or as a hider and build your shelters from cars or office desks, hide in the water, in the hay pile, in the cornfield, in the boss'' office and most importantly, push others in the seeker''s vision field. Try to be kind though.' FROM games WHERE igdb_id = 229879 ON CONFLICT (game_id, language_code) DO NOTHING;
