INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The World', '小明因黑人抬棺穿越到神秘新大陆开始了传（造）奇（孽）的一生。这是一款颠覆性的RPG扮演类游戏，是一个完全的开放性世界，你不再被主线剧情所拘束可以自由的在这个世界的各个角落探索，寻找宝物，或是完成一件件难忘的冒险。在游戏中做一个坏人亦或者是一个好人都由你自己决定，你还可以加入各种门派，学习绝学，制作装备炼制法宝等等，直到你从一个屌丝成长为一个大屌丝！' FROM games WHERE igdb_id = 158923 ON CONFLICT (game_id, language_code) DO NOTHING;
