INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'LocO-SportS', 'LocO-SportS is a fun sports game held at an Olympic stadium. Compete with your friends and family to be the best while you laugh at craziest and most surreal events. Reach impossible records such as a 25-metre high pole vault. Compete with the most diverse athletes in the world - a jovial 90-year-old grandmother, a hippie, a clown, an emo, a biker, a thief, a policeman, a punk, a fireman, a diver, a boxer, a superhero...even a handsome disco guy, the list goes on.' FROM games WHERE igdb_id = 147744 ON CONFLICT (game_id, language_code) DO NOTHING;
