INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Frozen Friends', 'Join the Ice Queen and her Frozen Friends in this endless jumping adventure! Help the Ice Queen escape the frozen forest and make it back to the kingdom all while avoiding evil monsters along the way! Collect coins and use them to open up MAGIC treasure chests filled with more Frozen Friends tocollect and play with! Play as Black Beard, Greta Goblin and MANY, MANY MORE! Also use your coins to buy POWERUPS to last longer in this endless frozen adventure! Magical powerups like the invincibility shield will help you avoid enemies and reach high scores!' FROM games WHERE igdb_id = 146683 ON CONFLICT (game_id, language_code) DO NOTHING;
