INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('starlit-adventures-golden-stars', 147627, '2020-07-17', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co4dqg.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/araki.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Starlit Adventures Golden Stars', 'Join Bo & Kikki for single-player or multiplayer fun anytime! Take on this family-friendly, vertical scrolling adventure with up to three friends as you try to save the Starlits and recover all the stars taken by Nuru. Comes with all suits including Unicorn, Dino and Dragon Golden Suit as playable characters! Three games in one, for triple the fun! Simple, straightforward controls, optimized for younger and less-experienced players, make this a perfect choice for anyone looking to introduce their family to the wonderful world of Starlit. For multiplayer, all a player needs is a Joy-Con, so two people can team up right out of the box! Tackle 144 platforming courses in the two main game modes: Story and Challenges! Enjoy extra replayability with the game mode Infinite Tower!' FROM games WHERE igdb_id = 147627 ON CONFLICT (game_id, language_code) DO NOTHING;
