INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Last Train: Final Ride', 'The Last Train is a Survival Adventure Game where you take the role of one of the last surviving train pilot in a post World War 2 America. The game is set in Alternate History, post the Hiroshima and Nagasaki bombings. In this emotional journey, the story explores how war affects ordinary citizens who want to go about their day to day lives, not just the brave soldiers who fight on the front lines.
