INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Turbo Sprint', 'Turbo Sprint is based on the classic arcade game Super Sprint. The game features 8 tracks that range in difficulty, up to four players can take control of either a Blue, Red, Yellow or Green car. Cars that are not controlled by players are computer controlled. When all 8 tracks have been completed the game loops back to the first track but the difficulty is increased with various obstacles and increased speed of the computer controlled cars. New players have the opportunity to join a race after each track has been completed.' FROM games WHERE igdb_id = 229785 ON CONFLICT (game_id, language_code) DO NOTHING;
