INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Killer Sudoku', 'In Killer Sudoku, every puzzle features cages that tell you the sum of the numbers inside. This extra information leads to beautiful logic that you will master as you progress through our handmade puzzles. The puzzles in Killer Sudoku are created by Simon and Mark as well as a large number of guest creators. Fans of Cracking the Cryptic''s YouTube channel will recognize many of these authors as some of the most talented creators working today!' FROM games WHERE igdb_id = 153688 ON CONFLICT (game_id, language_code) DO NOTHING;
