INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('dethcube', 148487, '2020-05-20', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co460d.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar5b07.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dethcube', '《激战魔方》是一款机甲题材的射击闯关游戏。玩家需要操控角色与魔方星球上强大的敌人进行战斗。随机地图、随机刷怪、随机装备获取，再加上怪物多变的弹幕组合让玩家每一局游戏都可获得不同的畅快战斗体验。而天赋及科技系统的加入更可以让角色有着不同的发展倾向，带来不同的战斗体验。' FROM games WHERE igdb_id = 148487 ON CONFLICT (game_id, language_code) DO NOTHING;
