INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Burning Mountain and Sea', '《烈山海》是一款以中国神话为背景的RPG游戏，玩家在游戏中将扮演一位身负奇异命运的穿越者，在机缘巧合之下来到山海境，与神农、夸父、精卫等经典神话人物相遇，一边改写他们的命运，一边完成自己的冒险……' FROM games WHERE igdb_id = 150681 ON CONFLICT (game_id, language_code) DO NOTHING;
