INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'ZOnOt''S Challenge', 'ZOnOt is a puzzle/ action game consisting of an A.I. powered machine who entraps you in its under water cavern and challenges solve puzzles to escape!! While teasing you in its own created language, it challenges you with ever increasing gates of difficulty. You must unlock each one in order to reach the surface, but what awaits you once you''re free??? So have fun with ZOnOt, an awesome puzzle + arcade + action game for the whole family!' FROM games WHERE igdb_id = 175545 ON CONFLICT (game_id, language_code) DO NOTHING;
