INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('hyena-squad', 175206, '2020-09-09', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co9g6e.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scvib7.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Hyena Squad', 'Hyena Squad is turn-based, tactical game that combines classic squad tactics with light RPG elements. Set in a deep space station infested with aliens and the animated dead, you will lead an elite team of specialists in a daring rescue mission. Use each of your team mates special skills to their fullest to hold back the alien hordes long enough to achieve your mission objectives and get your squad out alive. The game features intense action where you will have to factor in cover, line of sight, alien positions, and squad morale to make the right decisions for victory. Lead a diverse squad ranging from heavily armored melee specialists, heavy gunners that can unleash a torrent of bullets, elusive and flexible scouts and even mysterious psychics.' FROM games WHERE igdb_id = 175206 ON CONFLICT (game_id, language_code) DO NOTHING;
